@push('scripts')<script>$(function(){const t=$('#production-cost-table'),x=$.fn.dataTable.render.text(),num=$.fn.dataTable.render.number(',','.',2),dt=t.DataTable($.extend(true,{},window.erpDataTableDefaults,{ajax:{url:t.data('url'),data:function(d){d.status=$('#cost-status').val();d.date_from=$('#cost-from').val();d.date_to=$('#cost-to').val();}},order:[[1,'desc']],buttons:[window.erpExcelButton(t)],columns:[window.erpRowNumberColumn(),{data:'document_number',name:'document_number',render:function(v,z,r){return z==='display'?'<a href="'+x.display(r.show_url)+'">'+x.display(v)+'</a>':v;}},{data:'item_label',name:'item_label',render:x.display},{data:'issued',className:'text-end',render:num},{data:'returned',className:'text-end',render:num},{data:'scrap',className:'text-end',render:num},{data:'finished',className:'text-end',render:num},{data:'available',className:'text-end fw-semibold',render:num},{data:'unit_cost',className:'text-end',render:function(v,z){return z==='display'&&v!==null?num.display(v):v;}},{data:null,orderable:false,searchable:false,className:'text-end',render:function(v,z,r){return z==='display'?'<a class="btn btn-sm btn-app-soft" href="'+x.display(r.show_url)+'" title="ดูรายละเอียด" aria-label="ดูรายละเอียด"><i class="bx bx-show" aria-hidden="true"></i></a>':'';}}]}));$('#cost-report-filters').on('submit',function(e){e.preventDefault();dt.ajax.reload();});$('#cost-reset').on('click',function(){$('#cost-report-filters')[0].reset();dt.ajax.reload();});});</script>@endpush
